    gapFilterEnabled: true,
    gapMaxPct: 3.0,                         // 당일 시가가 전일 종가 대비 +N% 초과 갭업 돌파 → 추격 비용↑
    gapScale: 0.7,                          //   → 사이즈 ×0.7 (갭업 돌파는 되돌림 확률 높음)
    clvEnabled: true,                       // CLV = (종가-저가)/(고가-저가): 일중 매수 강도
