// 정도부사(강조/감쇠). 곱이 아니라 VADER식 가산 스칼라.
const SENTI_BOOST = {
  "very":0.293,"really":0.293,"extremely":0.393,"absolutely":0.393,"incredibly":0.393,"hugely":0.35,
  "so":0.25,"too":0.2,"massively":0.4,"significantly":0.3,"substantially":0.3,"sharply":0.35,"strongly":0.3,
  "slightly":-0.293,"somewhat":-0.2,"barely":-0.35,"marginally":-0.3,"kinda":-0.15,"partially":-0.2,
  // [V12] 강조어 확장
  "notably":0.3,"remarkably":0.35,"dramatically":0.4,"steeply":0.35,"vastly":0.38,"modestly":-0.2,"mildly":-0.25 };
const SENTI_NEGATE = { "not":1,"no":1,"never":1,"none":1,"nobody":1,"nothing":1,"neither":1,"nowhere":1,
  "cannot":1,"can't":1,"won't":1,"wouldn't":1,"don't":1,"doesn't":1,"didn't":1,"isn't":1,"aren't":1,
  "wasn't":1,"weren't":1,"without":1,"lack":1,"lacks":1,"fails":1,"failed":1,"denies":1,"denied":1,"rejects":1,
  "hardly":1,"scarcely":1,"unlikely":1 };
const SENTI_NEG_SCALE = -0.74; // VADER 부정 반전계수
const SENTI_CAP_INCR = 0.733;  // 대문자 강조 증분
const SENTI_EXCL_INCR = 0.292; // '!' 강조(최대 4개)
const SENTI_QUES_INCR = 0.18;

function _sTokenize(text) {
  // [V10] 한글(가-힣) 보존 — 기존 \w는 한국어를 전부 제거해 KR 뉴스 감성이 0이던 버그 수정.
  return (typeof text === "string" ? text : "").replace(/[^\w'!?$%.가-힣 ]+/g, " ").split(/\s+/).filter(Boolean);
}
function _sIsCapDiff(tokens) { // 일부만 대문자면 강조로 인정(전부 대문자면 무시)
  let caps = 0, words = 0;
  for (const t of tokens) { const w = t.replace(/[^A-Za-z]/g, ""); if (w.length >= 2) { words++; if (w === w.toUpperCase()) caps++; } }
  return words > 0 && caps > 0 && caps < words;
}

// 단일 텍스트 → compound [-1,1] + 세부. VADER 규칙 축약구현.
function sentimentScore(text) {
  try {
    const rawTokens = _sTokenize(text);
    if (!rawTokens.length) return { compound: 0, pos: 0, neg: 0, n: 0 };
    const capDiff = _sIsCapDiff(rawTokens);
    const lower = rawTokens.map(function (t) { return t.toLowerCase(); });
    let sentiments = [];
    for (let i = 0; i < lower.length; i++) {
      const bareToken = lower[i].replace(/[!?.]+$/g, "");
      let v = SENTI_LEX[bareToken];
      if (v === undefined) { sentiments.push(0); continue; }
      // 대문자 강조
      const orig = rawTokens[i].replace(/[^A-Za-z]/g, "");
      if (capDiff && orig.length >= 2 && orig === orig.toUpperCase()) v += (v > 0 ? SENTI_CAP_INCR : -SENTI_CAP_INCR);
      // 앞쪽 3단어 내 강조어/부정어
      for (let d = 1; d <= 3 && i - d >= 0; d++) {
        const prev = lower[i - d].replace(/[!?.]+$/g, "");
        const b = SENTI_BOOST[prev];
        if (b !== undefined) { let inc = b; if (d === 2) inc *= 0.95; if (d === 3) inc *= 0.9; v += (v > 0 ? inc : -inc); }
        if (SENTI_NEGATE[prev]) v *= SENTI_NEG_SCALE;
      }
      sentiments.push(v);
    }
    // 대조접속사 "but": 앞은 0.5배, 뒤는 1.5배
    const bi = lower.indexOf("but");
    if (bi !== -1) { for (let i = 0; i < sentiments.length; i++) sentiments[i] *= (i < bi ? 0.5 : 1.5); }
    let sum = 0, pos = 0, neg = 0;
    for (const s of sentiments) { sum += s; if (s > 0) pos += s + 1; else if (s < 0) neg += Math.abs(s) - 1; }
    // 문장부호 강조
    const excl = Math.min((text.match(/!/g) || []).length, 4);
    const ques = Math.min((text.match(/\?/g) || []).length, 4);
    let punct = excl * SENTI_EXCL_INCR; if (ques >= 2) punct += ques * SENTI_QUES_INCR;
    if (sum > 0) sum += punct; else if (sum < 0) sum -= punct;
    const compound = sum / Math.sqrt(sum * sum + 15); // VADER 정규화(α=15)
    return { compound: _clamp(compound, -1, 1), pos: pos, neg: neg, n: rawTokens.length };
  } catch (e) { return { compound: 0, pos: 0, neg: 0, n: 0 }; }
}

// 헤드라인/포스트 배열 → 집계 감성 + lux_news 태거 결합.
//   반환: { sent(-3..3 스케일), compound(-1..1 평균), pos, neg, n, types, tags }
//   nlpTagHeadlines의 사건분류(mna/reg/...)와 VADER 극성을 함께 제공.
function nlpTagHeadlinesV2(headlines) {
  const base = nlpTagHeadlines(headlines); // 사건타입/사전극성(기존)
  try {
    if (!Array.isArray(headlines) || !headlines.length) return Object.assign(base, { compound: 0, pos: 0, neg: 0 });
    let cSum = 0, pos = 0, neg = 0, cnt = 0;
    for (const raw of headlines) {
      const h = (typeof raw === "string") ? raw : (raw && (raw.title || raw.headline || raw.text)) || "";
      if (!h) continue;
      const s = sentimentScore(h);
      cSum += s.compound; pos += s.pos; neg += s.neg; cnt++;
    }
    const compound = cnt ? cSum / cnt : 0;
    // VADER compound를 lux_news의 sent(-3..3) 스케일로 투영하고 사전극성과 평균결합
    const vaderSent = _clampN(compound * 3, -3, 3);
    base.compound = +compound.toFixed(3);
    base.pos = +pos.toFixed(2); base.neg = +neg.toFixed(2);
    base.sent = _clampN((base.sent + vaderSent) / 2, -3, 3); // 사건사전 + VADER 융합
  } catch (e) {}
  return base;
}

// ============================================================================
// [V14] 고도화 뉴스/감성 스코어러 — 여의도 문법·연관성·시간·중복·오버라이드
//   일반 VADER(sentimentScore) 위에 금융 도메인 레이어를 얹는다:
//     1) 필터링·연관성 : 개체명 연관성, 매체 신뢰도, 중복기사 페널티
//     2) 금융 특화     : 금융 문맥 극성반전(금리인하·부채감소=호재), 강도 컷오프, 혼재 처리
//     3) 시간·반응     : 뉴스 반감기 감쇠, 선반영(추격) 차단, 거래량-뉴스 동조 교차검증
//     4) 오버라이드    : 횡령·배임·상폐 등 치명 악재 → 기술신호 무시하고 매수금지·전량매도
//   파라미터는 AI_PARAMS.sentiment 에서 조회. LLM 0.
// ============================================================================

// 금융 문맥 극성(구절 포함 매칭 — 토큰화 전 원문 소문자에서 includes). 일반어와 정반대인 케이스 위주.
const SENTI_FIN_CONTEXT = {
  // 호재(일반적으론 '인하/감소/축소'라 부정적으로 보일 수 있으나 시장에선 +)
  "rate cut": 1.8, "rate cuts": 1.8, "cuts rates": 1.8, "cut interest": 1.6, "dovish": 1.4,
  "debt reduction": 1.6, "reduces debt": 1.5, "deleveraging": 1.2, "cost cutting": 1.0, "cost reduction": 1.0,
  "tax cut": 1.5, "tax cuts": 1.5, "buyback": 1.6, "stock split": 0.8, "short squeeze": 1.4, "oversold": 0.8,
  "금리 인하": 1.8, "금리인하": 1.8, "기준금리 인하": 1.8, "부채 감소": 1.6, "부채감소": 1.6, "차입금 감소": 1.4,
  "원가 절감": 1.0, "비용 절감": 1.0, "감세": 1.5, "자사주 매입": 1.6, "자사주매입": 1.6, "과매도": 0.8,
  // 악재(일반적으론 '인상/증가'라 긍정처럼 보일 수 있으나 시장에선 −)
  "rate hike": -1.3, "rate hikes": -1.3, "hikes rates": -1.3, "hawkish": -1.1, "debt surge": -1.4,
  "rising debt": -1.2, "dilution": -1.6, "share dilution": -1.8, "capital raise": -1.2, "overbought": -0.8,
  "금리 인상": -1.3, "금리인상": -1.3, "기준금리 인상": -1.3, "부채 급증": -1.4, "차입금 증가": -1.1,
  "유상증자": -1.6, "주식 희석": -1.6, "과매수": -0.8
};

// 치명 악재(오버라이드) — 종목과 함께 등장 시 매수금지·전량매도. 소문자 부분매칭.
const SENTI_CRITICAL_NEG = [
  "횡령", "배임", "분식", "분식회계", "회계부정", "상장폐지", "상폐", "거래정지", "감사의견 거절", "감사의견거절",
  "의견거절", "자본잠식", "부도", "파산", "회생절차", "법정관리", "상장적격성", "불성실공시", "관리종목 지정",
  "내부자 거래", "주가조작", "시세조종", "대규모 손실",
  "embezzlement", "accounting fraud", "financial fraud", "fraud charges", "sec charges", "delisting",
  "delisted", "bankruptcy", "chapter 11", "going concern", "insolvency", "default on", "ponzi", "restatement",
  "auditor resign", "sec investigation", "sec probe", "criminal charges", "indicted"
];

// 기사에서 매체(source) 추정 — 구글뉴스 제목 접미(" - Reuters") 또는 링크 도메인.
function _articleSource(art) {
  try {
    const title = (art && (art.title || art.headline)) || (typeof art === "string" ? art : "");
    let src = (art && art.source) || "";
    if (!src && title) { const m = title.match(/\s[-–—]\s([^-–—]{2,40})$/); if (m) src = m[1].trim(); }
    if (!src && art && art.link) { const dm = String(art.link).match(/https?:\/\/(?:www\.)?([^\/]+)/); if (dm) src = dm[1]; }
    return src.toLowerCase();
  } catch (e) { return ""; }
}
function _sourceWeight(src, sw) {
  if (!src) return (sw && sw.unknown) || 1.0;
  const keys = { "dart": "dart", "sec.gov": "sec", "bloomberg": "bloomberg", "reuters": "reuters", "wsj": "wsj",
    "wall street": "wsj", "financial times": "ft", "ft.com": "ft", "cnbc": "cnbc", "yonhap": "yonhap", "연합": "yonhap",
    "매일경제": "mk", "mk.co.kr": "mk", "한국경제": "hankyung", "hankyung": "hankyung", "blog": "blog", "tistory": "blog", "naver.me": "blog" };
  for (const k in keys) if (src.indexOf(k) !== -1) return (sw && sw[keys[k]]) || 1.0;
  return (sw && sw.unknown) || 1.0;
}
// 금융 문맥 극성 보정(구절 매칭 합).
function _finContextAdjust(lowerText) {
  let adj = 0;
  for (const p in SENTI_FIN_CONTEXT) if (lowerText.indexOf(p) !== -1) adj += SENTI_FIN_CONTEXT[p];
  return _clamp(adj, -3, 3);
}
// 개체명 연관성 — 종목/회사명이 헤드라인 주제인지(가중↑) 단순나열인지(가중↓).
function _entityRelevance(lowerTitle, symbol, companyName, er) {
  try {
    er = er || {};
    const names = [];
    if (companyName) names.push(String(companyName).toLowerCase());
    if (symbol) { const base = String(symbol).replace(/\.(KS|KQ)$/i, "").toLowerCase(); if (base) names.push(base); }
    let cnt = 0, inHead = false;
    for (const nm of names) {
      if (!nm || nm.length < 2) continue;
      const idx = lowerTitle.indexOf(nm);
      if (idx !== -1) { cnt++; if (idx < Math.max(40, lowerTitle.length * 0.5)) inHead = true; }
    }
    if (cnt === 0) return (er.listingOnlyWeight != null ? er.listingOnlyWeight : 0.4); // 언급 없음 → 섹터 나열 취급
    let w = 1.0;
    if (inHead) w *= (er.headlineBonus || 1.5);
    if (cnt >= 2) w *= (1 + (er.mentionBonus || 0.3));
    return _clamp(w, 0.2, 3);
  } catch (e) { return 1.0; }
}
// 제목 자카드 유사도(중복 판정).
function _titleJaccard(a, b) {
  try {
    const ta = new Set(a.toLowerCase().split(/\s+/).filter(function (t) { return t.length > 1; }));
    const tb = new Set(b.toLowerCase().split(/\s+/).filter(function (t) { return t.length > 1; }));
    if (!ta.size || !tb.size) return 0;
    let inter = 0; for (const t of ta) if (tb.has(t)) inter++;
    return inter / (ta.size + tb.size - inter);
  } catch (e) { return 0; }
}

// ── 고도화 스코어러 ──────────────────────────────────────────
//   articles: [{title, link?, pub?, source?}] 또는 문자열 배열
//   opts: { symbol, companyName, nowTs, priceRunupPct, volRatio, params(AI_PARAMS.sentiment) }
//   반환: { compound(-1..1), sent(-3..3), confirmedBuy, chaseBlocked, abstain, override, overrideKw, n, effN, flags }
function scoreNewsAdvanced(articles, opts) {
  opts = opts || {};
  const P = opts.params || ((typeof AI_PARAMS !== "undefined" && AI_PARAMS.sentiment) || {});
  const out = { compound: 0, sent: 0, confirmedBuy: false, chaseBlocked: false, abstain: false,
    override: false, overrideKw: null, n: 0, effN: 0, flags: {} };
  try {
    const arr = (Array.isArray(articles) ? articles : []).map(function (a) {
      return (typeof a === "string") ? { title: a } : (a || {});
    }).filter(function (a) { return a.title; });
    if (!arr.length) return out;
    const now = opts.nowTs || Date.now();
    const seen = [];  // 중복판정용 이미 채택된 제목들
    let wSum = 0, wComp = 0, posMax = 0, negMax = 0;
    for (const a of arr) {
      const title = String(a.title);
      const low = title.toLowerCase();
      // 오버라이드(치명 악재) — 종목 연관 있을 때만 발동(연관 없으면 섹터 노이즈)
      const rel = _entityRelevance(low, opts.symbol, opts.companyName, P.entityRelevance);
      if (P.overrideEnabled !== false && rel >= 1.0) {
        for (const kw of SENTI_CRITICAL_NEG) { if (low.indexOf(kw) !== -1) { out.override = true; out.overrideKw = kw; break; } }
      }
      // 기본 VADER + 금융 문맥 보정
      const base = sentimentScore(title).compound;
      const fin = _finContextAdjust(low) / 4;   // -0.75..0.75 스케일
      let c = _clamp(base + fin, -1, 1);
      // 혼재 뉘앙스 추적(한 기사 내 pos·neg 동시 강)
      if (base > 0) posMax = Math.max(posMax, base); else if (base < 0) negMax = Math.max(negMax, -base);
      // 매체 신뢰도 × 개체명 연관성 × 반감기 감쇠
      const srcW = _sourceWeight(_articleSource(a), P.sourceWeights);
      let hl = (P.halfLifeMinutes && P.halfLifeMinutes.default) || 720;
      if (/속보|breaking|긴급/.test(low)) hl = (P.halfLifeMinutes && P.halfLifeMinutes.breaking) || 30;
      else if (/공시|filing|8-k|dart|사업보고서/.test(low)) hl = (P.halfLifeMinutes && P.halfLifeMinutes.filing) || 10080;
      let decay = 1;
      const ts = a.pub ? Date.parse(a.pub) : (a.ts || 0);
      if (ts && isFinite(ts) && ts > 0) { const ageMin = Math.max(0, (now - ts) / 60000); decay = Math.pow(0.5, ageMin / hl); }
      // 중복 페널티 — 이미 채택된 유사 제목이 있으면 축소
      let dupW = 1;
      for (const s of seen) { if (_titleJaccard(title, s) >= (P.duplicateSimilarity || 0.8)) { dupW = (P.duplicatePenalty != null ? P.duplicatePenalty : 0.5); break; } }
      seen.push(title);
      const w = srcW * rel * decay * dupW;
      wSum += w; wComp += w * c; out.n++;
    }
    if (wSum <= 0) return out;
    let compound = _clamp(wComp / wSum, -1, 1);
    out.effN = +wSum.toFixed(2);
    // 혼재 처리 — 호·악재 모두 강하면 상계(net) 또는 보류(hold)
    if (posMax >= (P.mixedConflictGap || 0.5) && negMax >= (P.mixedConflictGap || 0.5)) {
      out.flags.mixed = true;
      if ((P.mixedHandling || "net") === "hold") { out.abstain = true; compound = 0; }
    }
    // 선반영(추격) 차단 — 뉴스 전 급등 상태면 호재라도 추격 금지
    if (typeof opts.priceRunupPct === "number" && opts.priceRunupPct >= (P.priceInThresholdPct || 8) && compound > 0) {
      out.chaseBlocked = true; out.flags.priceIn = +opts.priceRunupPct.toFixed(1);
    }
    // 거래량-뉴스 동조 교차검증 — 호재인데 거래량 안 붙으면 확신 감쇠
    let volOK = true;
    if (typeof opts.volRatio === "number" && compound > 0) { volOK = opts.volRatio >= (P.volumeConfirmMult || 1.5); out.flags.volRatio = +opts.volRatio.toFixed(2); }
    // 확실한 매수 시그널 — 강도 컷오프 + 거래량 확인 + 추격아님 + 최소기사수
    out.confirmedBuy = compound >= (P.intensityThreshold || 0.7) && volOK && !out.chaseBlocked && !out.abstain && out.n >= (P.minHeadlines || 2);
    out.compound = +compound.toFixed(3);
    out.sent = +_clampN(compound * 3, -3, 3).toFixed(3);
  } catch (e) {}
  return out;
}

// 보유/후보 종목의 치명 악재 오버라이드 여부 — 섹터 헤드라인에서 종목 연관 치명키워드 탐지.
//   반환: { hit, kw } (hit=false면 없음). 결과는 호출부 사이클 캐시로 재사용 권장.
function sentiSymbolOverride(symbol, companyName, sectorNews, mcfg) {
  try {
    const P = (typeof AI_PARAMS !== "undefined" && AI_PARAMS.sentiment) || {};
    if (P.overrideEnabled === false || !sectorNews || !sectorNews.headlines) return { hit: false };
    const grp = (typeof getSectorGroup === "function") ? getSectorGroup(symbol, mcfg) : null;
    const buckets = [];
    if (grp && sectorNews.headlines[grp]) buckets.push(sectorNews.headlines[grp]);
    if (sectorNews.headlines.MARKET) buckets.push(sectorNews.headlines.MARKET);
    for (const arts of buckets) {
      const r = scoreNewsAdvanced(arts, { symbol: symbol, companyName: companyName, params: P });
      if (r.override) return { hit: true, kw: r.overrideKw };
    }
    return { hit: false };
  } catch (e) { return { hit: false }; }
}


// ============================================================================
// [FETCH] 외부 뉴스/감성 수집 파이프라인 (Worker fetch → 감성 → state)
//   RSS(XML) 및 JSON 엔드포인트에서 헤드라인을 끌어와 종목/섹터별로 감성 집계,
//   lux_news가 이미 읽는 state "sector_news_sentiment"에 기록한다(+심볼별 캐시).
//   ★ 소스 URL은 사용자가 SENTI_SOURCES에 채운다(예: 구글뉴스 RSS, 종목 API).
//   네트워크 실패/파싱실패는 전부 무해 폴백(감성 없으면 뉴스피처 0).
// ============================================================================

// [V9] 무료 구글뉴스 RSS(무키) — 섹터그룹 키(TECH/FINANCE/…)에 매핑해 기존 sector_news_sentiment를 보강.
//   야간 1회 수집(6 subreq) → VADER 감성 → newsSent 피처 강화. 그룹키는 SECTOR_NEWS_REP과 동일해야 라이브 피처가 읽음.
//   ※ 뉴스감성은 과거봉 소급수확 불가 → 라이브 표본에만 반영(느리게 축적). 노이즈는 L1/신뢰게이트가 자동 억제.
const _GNEWS = function (q) { return "https://news.google.com/rss/search?q=" + encodeURIComponent(q) + "&hl=en-US&gl=US&ceid=US:en"; };
const _GNEWSK = function (q) { return "https://news.google.com/rss/search?q=" + encodeURIComponent(q) + "&hl=ko&gl=KR&ceid=KR:ko"; }; // [V14] 한국어 뉴스
const SENTI_SOURCES = [
  { type: "rss", group: "TECH",       url: _GNEWS("semiconductor OR AI chip OR Nvidia OR Apple OR Microsoft stock") },
  { type: "rss", group: "TECH",       url: _GNEWS("artificial intelligence stocks OR TSMC OR AMD OR chip earnings OR cloud software") },
  { type: "rss", group: "TECH",       url: _GNEWS("Broadcom OR Micron OR ASML OR Qualcomm OR data center OR GPU demand") },   // [V14]
  { type: "rss", group: "FINANCE",    url: _GNEWS("bank stocks OR JPMorgan OR interest rate OR financial sector earnings") },
  { type: "rss", group: "FINANCE",    url: _GNEWS("Federal Reserve OR Goldman Sachs OR bond yields OR credit spreads OR insurance stocks") }, // [V14]
  { type: "rss", group: "HEALTH",     url: _GNEWS("pharma stocks OR FDA approval OR healthcare sector OR Eli Lilly OR biotech") },
  { type: "rss", group: "HEALTH",     url: _GNEWS("clinical trial OR drug approval OR Merck OR Pfizer OR medical device stocks") },   // [V14]
  { type: "rss", group: "CONSUMER",   url: _GNEWS("retail stocks OR Amazon OR Tesla OR consumer spending OR Walmart") },
  { type: "rss", group: "CONSUMER",   url: _GNEWS("EV sales OR electric vehicle OR Nike OR Starbucks OR consumer confidence") },
  { type: "rss", group: "INDUSTRIAL", url: _GNEWS("defense stocks OR Boeing OR Caterpillar OR industrial sector OR aerospace") },
  { type: "rss", group: "INDUSTRIAL", url: _GNEWS("robotics OR machinery orders OR GE Aerospace OR Lockheed OR industrial demand") }, // [V14]
  { type: "rss", group: "RESOURCES",  url: _GNEWS("oil price OR energy stocks OR Exxon OR commodities OR natural gas") },
  { type: "rss", group: "RESOURCES",  url: _GNEWS("gold price OR copper OR lithium OR metals OR mining stocks") },
  // MARKET = 광의 시장감성(미매핑 종목·시장 폴백용)
  { type: "rss", group: "MARKET",     url: _GNEWS("stock market today OR S&P 500 OR Nasdaq OR Dow Jones rally OR selloff") },
  { type: "rss", group: "MARKET",     url: _GNEWS("analyst upgrade OR price target raised OR earnings beat OR guidance raised") },
  { type: "rss", group: "MARKET",     url: _GNEWS("VIX OR market volatility OR recession fears OR Fed rate decision OR jobs report") }, // [V14]
  // [V14] 한국어 소스 — KR 종목 감성·오버라이드(횡령·상폐 등) 탐지 강화
  { type: "rss", group: "MARKET",     url: _GNEWSK("코스피 OR 코스닥 OR 삼성전자 OR SK하이닉스 OR 증시") },
  { type: "rss", group: "TECH",       url: _GNEWSK("반도체 OR 2차전지 OR AI 반도체 OR 삼성전자 실적 OR 하이닉스") },
  { type: "rss", group: "FINANCE",    url: _GNEWSK("은행주 OR 금리 OR 증권주 OR 실적 발표 OR 배당") },
  { type: "rss", group: "MARKET",     url: _GNEWSK("상장폐지 OR 횡령 OR 배임 OR 분식회계 OR 거래정지 OR 감사의견") }  // 치명 악재 전담
];

function _rssTitles(xml) {
  const out = [];
  try {
    const re = /<title>([\s\S]*?)<\/title>/gi;
    let m; let first = true;
    while ((m = re.exec(xml)) !== null) {
      if (first) { first = false; continue; } // 첫 title은 대개 피드명
      let t = m[1].replace(/<!\[CDATA\[/g, "").replace(/\]\]>/g, "").replace(/&[a-z]+;/g, " ").trim();
      if (t) out.push(t);
      if (out.length >= 40) break;
    }
  } catch (e) {}
  return out;
}
function _jsonExtract(obj, path, field) {
  const out = [];
  try {
    let arr = obj;
    if (path) for (const key of path.split(".")) arr = arr ? arr[key] : null;
    if (Array.isArray(arr)) for (const it of arr) { const v = field ? it[field] : it; if (typeof v === "string" && v) out.push(v); if (out.length >= 40) break; }
  } catch (e) {}
  return out;
}

// 사이클당 1회(스케줄) 호출. fetchImpl 주입가능(테스트용). 기본은 전역 fetch.
//   ① 추가 소스(SENTI_SOURCES) fetch → 기존 state에 병합(V83 {title,link,pub} 형식 유지)
//   ② 소스가 없어도, V83 섹터뉴스 수집기가 6시간마다 모아둔 헤드라인에 VADER 감성을
//      계산해 같은 state의 sentiment 필드로 병합(네트워크 0). scales/scores는 보존.
async function sentiFetchAndStore(DB, sources, fetchImpl) {
  const F = fetchImpl || (typeof fetch !== "undefined" ? fetch : null);
  const srcs = sources || SENTI_SOURCES;
  const byGroup = {};        // group → 헤드라인(문자열) 배열
  let fetched = 0;
  if (F && srcs.length) {
    for (const s of srcs) {
      try {
        const resp = await F(s.url, { cf: { cacheTtl: 300 } });
        if (!resp || !resp.ok) continue;
        let titles = [];
        if (s.type === "json") { const j = await resp.json(); titles = _jsonExtract(j, s.path, s.field || "title"); }
        else { const txt = await resp.text(); titles = _rssTitles(txt); }
        if (titles.length) { byGroup[s.group] = (byGroup[s.group] || []).concat(titles).slice(0, 60); fetched++; }
      } catch (e) {}
    }
  }
  // 기존 state 로드(V83 섹터뉴스 수집분) — 덮지 말고 병합
  let st = null;
  try { st = await getState(DB, "sector_news_sentiment", null); } catch (e) {}
  if (!st || typeof st !== "object") st = {};
  if (!st.headlines) st.headlines = {};
  // 추가 소스 헤드라인 병합(V83 소비자 호환을 위해 {title} 객체로)
  for (const g of Object.keys(byGroup)) {
    const cur = Array.isArray(st.headlines[g]) ? st.headlines[g] : [];
    const add = byGroup[g].map(function (t) { return { title: t, src: "senti" }; });
    st.headlines[g] = cur.concat(add).slice(0, 60);
  }
  // 전 그룹 VADER 감성 계산(기존+추가 헤드라인 전체 대상, 문자열/객체 모두 수용)
  const sentiment = {};
  const groups = Object.keys(st.headlines);
  for (const g of groups) {
    let acc = 0, c = 0;
    for (const h of st.headlines[g]) {
      const t = (typeof h === "string") ? h : ((h && h.title) || "");
      if (!t) continue;
      acc += sentimentScore(t).compound; c++;
    }
    if (c) sentiment[g] = { compound: +(acc / c).toFixed(3), n: c };
  }
  if (!Object.keys(sentiment).length) return "[SENTI] 수집 0건 — 스킵";
  st.sentiment = sentiment;
  st.sentimentAt = Date.now();
  try { await setState(DB, "sector_news_sentiment", st); } catch (e) {}
  return "[SENTI] VADER " + Object.keys(sentiment).length + "그룹" + (fetched ? " (+소스 " + fetched + ")" : "") + " " +
         Object.keys(sentiment).map(function (g) { return g + ":" + sentiment[g].compound; }).join(" ");
}


// ============================================================================
// [DATA-1] 반사실(counterfactual) 후보 라벨링
//   진입신호가 뜬 '모든 후보'(실매수 여부 무관)를 무라벨로 기록 → horizon일 뒤
//   가격변화로 승/패를 자동 라벨링해 ml_samples에 편입. 표본을 수~수십배로.
//   → 소표본/과적합의 근본해결: "산 것"만이 아니라 "봤던 것" 전부에서 배운다.
// ============================================================================

let _candTableReady = false;
async function mlEnsureCandTable(DB) {
  try {
    await DB.prepare(
      "CREATE TABLE IF NOT EXISTS ml_candidates (" +
      "id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER, market TEXT, symbol TEXT, " +
      "strategy TEXT, feat TEXT, entry_price REAL, stop_pct REAL, horizon INTEGER, featver INTEGER, labeled INTEGER DEFAULT 0)"
    ).run();
    if (!_candTableReady) {
      // 구버전 테이블(stop_pct 없음) 마이그레이션 + 인덱스(대기후보 스캔 가속) — 1회만.
      try { await DB.prepare("ALTER TABLE ml_candidates ADD COLUMN stop_pct REAL").run(); } catch (e) {}
      try { await DB.prepare("CREATE INDEX IF NOT EXISTS idx_cand_open ON ml_candidates(featver, labeled, ts)").run(); } catch (e) {}
      _candTableReady = true;
    }
  } catch (e) {}
}

// [배치용] 후보 INSERT 문 1건 생성(즉시 쓰지 않음). 호출부가 모아서 mlFlushCandidates로 1회 커밋.
//   → 종목×전략마다 개별 write하던 것을 사이클당 1배치로(D1 write 폭증 방지).
function mlCandidateStmt(DB, market, symbol, strategy, featVec, entryPrice, stopPct, horizonDays) {
  try {
    if (!LUXML.enabled) return null;
    if (!Array.isArray(featVec) || featVec.length !== LUXML.featNames.length) return null;
    if (!(entryPrice > 0)) return null;
    return DB.prepare(
      "INSERT INTO ml_candidates (ts, market, symbol, strategy, feat, entry_price, stop_pct, horizon, featver, labeled) VALUES (?,?,?,?,?,?,?,?,?,0)"
    ).bind(Date.now(), market, symbol, strategy || "swing", JSON.stringify(featVec),
           entryPrice, (stopPct > 0 ? stopPct : 5), horizonDays || 5, LUXML.featVer);
  } catch (e) { return null; }
}
async function mlFlushCandidates(DB, stmts) {
  try {
    if (!stmts || !stmts.length) return 0;
    await mlEnsureCandTable(DB);
    let n = 0;
    for (let i = 0; i < stmts.length; i += 100) { try { await DB.batch(stmts.slice(i, i + 100)); n += Math.min(100, stmts.length - i); } catch (e) {} }
    return n;
  } catch (e) { return 0; }
}
// [호환용] 즉시 1건 기록(배치를 안 쓰는 직접 호출자용). 핫패스에선 mlCandidateStmt 사용 권장.
async function mlLogCandidate(DB, market, symbol, strategy, featVec, entryPrice, horizonDays, stopPct) {
  const s = mlCandidateStmt(DB, market, symbol, strategy, featVec, entryPrice, stopPct, horizonDays);
  if (!s) return;
  try { await mlEnsureCandTable(DB); await s.run(); } catch (e) {}
}

// 야간 호출. priceLookup(symbol, market, entryTs, horizon) → 숫자(종가) 또는 {closes:[...]}(경로).
//   경로가 오면 horizon 구간 내 손절선 도달 여부를 판정해 손절가로 라벨(실거래와 정합) —
//   단순 buy&hold 낙관편향 제거. 라벨된 후보는 ml_samples로 편입 후 즉시 DELETE(테이블 정리).
async function mlLabelCandidates(DB, priceLookup, opts) {
  if (!LUXML.enabled) return null;
  try {
    await mlEnsureCandTable(DB); await mlEnsureTable(DB);
    // 구버전 잔여(labeled!=0) 정리 — 무한증식 방지(있으면 삭제).
    try { await DB.prepare("DELETE FROM ml_candidates WHERE labeled != 0").run(); } catch (e) {}
    // [V4] featVer 승격으로 라벨링 대상에서 영영 빠지는 구버전 후보 정리
    try { await DB.prepare("DELETE FROM ml_candidates WHERE featver != ?").bind(LUXML.featVer).run(); } catch (e) {}
    const maxAgeMs = ((opts && opts.maxHorizon) || 20) * 86400000;
    const now = Date.now();
    const rows = await DB.prepare(
      "SELECT id, market, symbol, strategy, feat, entry_price, stop_pct, horizon, ts FROM ml_candidates WHERE labeled = 0 AND featver = ? ORDER BY ts ASC LIMIT 3000"
    ).bind(LUXML.featVer).all();
    const cands = (rows && rows.results) ? rows.results : [];
    let labeled = 0, skipped = 0, purged = 0, deduped = 0;
    const delStmts = [];
    const seen = {}; // 같은 종목·전략·진입일 중복 표본 제거(여러 cron이 같은 날 반복로깅한 것)
    for (const c of cands) {
      const dueMs = (c.horizon || 5) * 86400000;
      if (now - c.ts < dueMs) { skipped++; continue; } // 아직 미성숙
      const entryDay = Math.floor(c.ts / 86400000);
      const key = c.symbol + "|" + (c.strategy || "") + "|" + entryDay;
      if (seen[key]) { delStmts.push(DB.prepare("DELETE FROM ml_candidates WHERE id=?").bind(c.id)); deduped++; continue; }
      let pr = null;
      try { pr = await priceLookup(c.symbol, c.market, c.ts, c.horizon || 5); } catch (e) {}
      const path = Array.isArray(pr) ? pr : (pr && Array.isArray(pr.closes) ? pr.closes : null);
      let exitPct = null;
      if (path && path.length) {
        const seg = path.slice(-(c.horizon || 5));
        const stopPct = (c.stop_pct > 0) ? c.stop_pct : 5;
        const stopLine = c.entry_price * (1 - stopPct / 100);
        // [V9.9] Triple-Barrier(de Prado) — 수확 라벨과 동일 규칙(라벨 일관성): 손절 우선 → 익절 → 만기.
        const tpLine = (typeof HARVEST !== "undefined" && HARVEST.tpPct > 0) ? c.entry_price * (1 + HARVEST.tpPct / 100) : Infinity;
        let hit = false;
        for (const p of seg) {
          if (!(p > 0)) continue;
          if (p <= stopLine) { exitPct = -stopPct; hit = true; break; }
          if (p >= tpLine) { exitPct = HARVEST.tpPct; hit = true; break; }
        }
        if (!hit) { const fin = seg[seg.length - 1]; if (fin > 0) exitPct = (fin - c.entry_price) / c.entry_price * 100; }
      } else if (typeof pr === "number" && pr > 0) {
        exitPct = (pr - c.entry_price) / c.entry_price * 100;
      }
      if (exitPct == null || !(c.entry_price > 0)) {
        if (now - c.ts > maxAgeMs) { delStmts.push(DB.prepare("DELETE FROM ml_candidates WHERE id=?").bind(c.id)); purged++; } // 가격 못 구한 만료분 정리
        continue;
      }
      let feat; try { feat = JSON.parse(c.feat); } catch (e) { delStmts.push(DB.prepare("DELETE FROM ml_candidates WHERE id=?").bind(c.id)); continue; }
      seen[key] = 1;
      // [V17] alpha 라벨용 지수 수익률 — 종목 경로와 동일 창(진입~만기)의 지수 수익
      let idxRet = null;
      if (pr && Array.isArray(pr.idxCloses) && pr.idxCloses.length >= 2) {
        const ic = pr.idxCloses, ie = ic[0], ix = ic[ic.length - 1];
        if (ie > 0 && ix > 0) idxRet = (ix / ie - 1) * 100;
      }
      await mlLogSample(DB, c.market, c.symbol, (c.strategy || "swing") + "_cf", feat, exitPct, idxRet);
      delStmts.push(DB.prepare("DELETE FROM ml_candidates WHERE id=?").bind(c.id)); // 편입 후 원본 제거
      labeled++;
    }
    for (let i = 0; i < delStmts.length; i += 100) { try { await DB.batch(delStmts.slice(i, i + 100)); } catch (e) {} }
    return "[CF] 반사실 라벨링 " + labeled + "건 편입" + (deduped ? "(+중복제거 " + deduped + ")" : "") +
           ", 미성숙 " + skipped + "건 대기" + (purged ? ", 만료정리 " + purged + "건" : "");
  } catch (e) { return "[CF] fail: " + (e && e.message); }
}


// ============================================================================
// [DATA-2] 백테스트 표본 주입기
//   과거 일봉으로 전략신호를 재현해 (피처, N일후수익) 표본을 대량 생성 → ml_samples.
//   한 번 돌려 수천~수만 표본을 즉시 확보(과적합 완화의 지름길).
//   featVer는 실거래와 동일 스펙을 쓰되 strategy에 "_bt" 접미사로 출처표시.
//
//   인자:
//     seriesBySym: { SYM: { closes:[...], market, dates?:[...] } }  (오래된→최신 순)
//     signalFn(window)→ { fire:bool, strategy, extra:{regime,sigWeight,confluence,dayPct} }
//         window = 그 시점까지의 closes 슬라이스. fire=true면 그 시점에 진입신호로 간주.
//     opts: { horizon=5, minBars=60, step=1, maxPerSym=500 }
// ============================================================================
async function mlBacktestInject(DB, seriesBySym, signalFn, opts) {
  if (!LUXML.enabled) return null;
  try {
    await mlEnsureTable(DB);
    const horizon = (opts && opts.horizon) || 5;
    const minBars = (opts && opts.minBars) || 60;
    const step = (opts && opts.step) || 1;
    const maxPerSym = (opts && opts.maxPerSym) || 500;
    let total = 0, syms = 0;
    for (const sym in seriesBySym) {
      const S = seriesBySym[sym];
      const closes = S && Array.isArray(S.closes) ? S.closes : null;
      if (!closes || closes.length < minBars + horizon + 1) continue;
      syms++;
      let made = 0;
      for (let t = minBars; t < closes.length - horizon && made < maxPerSym; t += step) {
        const win = closes.slice(0, t + 1);
        let sig; try { sig = signalFn(win, sym, S); } catch (e) { continue; }
        if (!sig || !sig.fire) continue;
        const price = closes[t];
        const future = closes[t + horizon];
        if (!(price > 0) || !(future > 0)) continue;
        const ex = sig.extra || {};
        const _sl = function (a) { return Array.isArray(a) ? a.slice(0, t + 1) : null; };  // [V9.4] OHLCV도 동일 슬라이스 → 수확·라이브 분포 정합
        const feat = mlBuildFeatures({
          closes: win, volumes: _sl(S.volumes), opens: _sl(S.opens), highs: _sl(S.highs), lows: _sl(S.lows),
          price: price, prevClose: t > 0 ? closes[t - 1] : 0, dayPct: _num(ex.dayPct, 0),
          regime: ex.regime || "NEUTRAL",
          sigWeight: _num(ex.sigWeight, 1), confluence: _num(ex.confluence, 1),
          strategy: sig.strategy || "swing", market: S.market, ev: ex.ev || {}
        });
        const pnlPct = (future - price) / price * 100;
        await mlLogSample(DB, S.market || "US", sym, (sig.strategy || "swing") + "_bt", feat, pnlPct);
        made++; total++;
      }
    }
    return "[BT] 백테스트 주입 " + total + "표본 / " + syms + "종목 (horizon=" + horizon + "일)";
  } catch (e) { return "[BT] fail: " + (e && e.message); }
}

async function sentiStatus(DB) {
  try {
    const s = await getState(DB, "sector_news_sentiment", null);
    let cand = 0, unl = 0, hvN = 0, tradeN = 0;
    try { const r = await DB.prepare("SELECT COUNT(*) c FROM ml_candidates WHERE featver=?").bind(LUXML.featVer).first(); cand = (r && r.c) || 0; } catch (e) {}
    try { const r = await DB.prepare("SELECT COUNT(*) c FROM ml_candidates WHERE labeled=0 AND featver=?").bind(LUXML.featVer).first(); unl = (r && r.c) || 0; } catch (e) {}
    try { const r = await DB.prepare("SELECT COUNT(*) c FROM ml_samples WHERE strategy='hv' AND featver=?").bind(LUXML.featVer).first(); hvN = (r && r.c) || 0; } catch (e) {}
    try { const r = await DB.prepare("SELECT COUNT(*) c FROM ml_samples WHERE strategy!='hv' AND featver=?").bind(LUXML.featVer).first(); tradeN = (r && r.c) || 0; } catch (e) {}
    return { sentimentGroups: s ? Object.keys(s.sentiment || {}).length : 0,
      sentimentUpdatedAt: s ? (s.sentimentAt || s.updatedAt || s.ts || null) : null,
      candidatesTotal: cand, candidatesUnlabeled: unl,
      samplesHarvested: hvN, samplesFromTrades: tradeN };
  } catch (e) { return { error: e && e.message }; }
}
export default {
  async fetch(request, env, ctx) { return handleRequest(request, env); },
  async scheduled(event, env, ctx) {
    // [FIX V8.8] 기존엔 runTradingCycle / refreshCommodityQuotes / runCommodityCycle을
    //   각각 ctx.waitUntil로 "동시" 실행했는데, 이들이 전역 __fetchBudget(yahoo fetch
    //   예산)을 공유하면서 서로 resetFetchBudget()로 카운터를 덮어쓰고 소진시켜
    //   가격/원자재 갱신이 산발적으로 실패했음(특히 정규장 1분 갱신).
    //   → 단일 promise 안에서 "순차" 실행해 각 사이클이 자기 예산을 온전히 쓰게 한다.
    const __cronStart = Date.now();
    __sleepAccumMs = 0;  // [실시간] invocation 시작마다 sleep 누적 초기화
    let __usageCalib = USAGE_LIMITS_DEFAULT.cpuCalibration;
    ctx.waitUntil((async () => {
      // [PAID 가드] Workers Paid 한도 90% 도달 시 모든 작업 차단 (초과 과금 방지)
      try {
        const _gcfg = migrateCfgToMarkets(Object.assign({}, DEFAULT_CFG, await getState(env.DB, "cfg", {})));
        if (_gcfg.usageLimits && typeof _gcfg.usageLimits.cpuCalibration === "number") __usageCalib = _gcfg.usageLimits.cpuCalibration;
        if (await isUsageShutdown(env.DB, _gcfg)) {
          // 사용량 누적은 계속 — 셧다운 상태에도 cron 자체는 카운트
          try { await tickUsage(env.DB, __cronStart, __usageCalib, 0); } catch (e) {}
          return;
        }
      } catch (e) {}

      // [V19] 0) LLM 일일 분석 — 거래 사이클보다 "먼저, 단독" 실행.
      //   293종목 거래 사이클(115s)과 같은 invocation에서 돌리면 LLM 외부 API fetch가
      //   시간/subrequest 예산 경쟁에 밀려 타임아웃났다(회귀 반복). 여기서 깨끗한 예산으로
      //   먼저 끝내고, 그 다음에 무거운 거래 사이클을 돌린다. 실패해도 거래는 정상 진행.
      try {
        // [V9.8] LLM 외부 API fetch는 깨끗한 subrequest 예산에서 시작해야 한다.
        //   __fetchBudget는 모듈 전역이라 warm isolate에선 직전 invocation의 거래 사이클이
        //   남긴 used(최대 45)가 그대로 이월돼 collectLLMContext의 budgetedFetch가 굶는다.
        //   여기서 리셋해 컨텍스트 수집·LLM 호출이 예산 경쟁 없이 돈다.
        try { resetFetchBudget(400); } catch (e0) {}  // [PAID] LLM context 수집용 (Paid 여유 활용)
        const _cfg = migrateCfgToMarkets(Object.assign({}, DEFAULT_CFG, await getState(env.DB, "cfg", {})));
        if (_cfg.llmHybrid && _cfg.llmHybrid.enabled) {
          const cdMin = _cfg.llmHybrid.failCooldownMin || 15;
          // [V9.8] 선(先)차감 쿨다운: 호출 시작 전에 실패 쿨다운을 먼저 찍는다.
          //   LLM fetch가 매달려 invocation이 통째로 죽으면(markLLMFailed 도달 못함) 다음 cron이
          //   곧장 재시도해 매분 60s씩 폭주했다(로그에 2분 간격 타임아웃 반복). 미리 찍어두면
          //   최악의 경우에도 cdMin 동안은 재시도 안 함. 성공하면 ranToday 마킹이 우선해 더는 호출 안 함.
          if (isLLMTriggerWindow("kr") && !(await llmAlreadyRanToday(env.DB, "kr")) && !(await llmInFailCooldown(env.DB, "kr"))) {
            await markLLMFailed(env.DB, "kr", cdMin);
            const r = await runLLMDailyAnalysis(env, "kr");
            if (r && r.ok) await markLLMRanToday(env.DB, "kr");
          }
          if (isLLMTriggerWindow("us") && !(await llmAlreadyRanToday(env.DB, "us")) && !(await llmInFailCooldown(env.DB, "us"))) {
            await markLLMFailed(env.DB, "us", cdMin);
            const r = await runLLMDailyAnalysis(env, "us");
            if (r && r.ok) await markLLMRanToday(env.DB, "us");
          }
        }
      } catch (e) { try { await log(env.DB, "ERROR", null, "[SCHED] LLM analysis fail: " + e.message); } catch (e2) {} }

      // 1) 주식/지수 가격 갱신 + 거래 (가장 무거움)
      try { await runTradingCycle(env); }
      catch (e) { try { await log(env.DB, "ERROR", null, "[SCHED] trading cycle fail: " + e.message); } catch (e2) {} }

      // 1.5) [V12.8] 신규 편입 종목 즉시 백필 + [V12.9] 오염 quote 전량 재기록 마이그레이션.
      //   - 백필: quote가 아예 없는 종목은 장 시간과 무관하게 사이클당 60개씩 채움.
      //   - 재기록: 과거 v8 롤오버 버그로 오염된 미국 quote 전체(560개)를 수정된 fetch로
      //     사이클당 60개씩 한 바퀴 다시 써서(기존 일봉 지표 보존 머지) 즉시 정상화. 1회성.
      try {
        const have = new Set();
        const rows = await env.DB.prepare("SELECT k FROM state WHERE k LIKE 'quote:%'").all();
        for (const r of ((rows && rows.results) || [])) have.add(String(r.k).slice(6));
        const missing = DEFAULT_US.concat(DEFAULT_KR).filter(function (s) { return !have.has(s); });
        let remig = [];
        const mig = await getState(env.DB, "quote_remigrate_v129", null);
        if (!mig || !mig.done) {
          const start = (mig && typeof mig.idx === "number") ? mig.idx : 0;
          remig = DEFAULT_US.slice(start, start + 60);
          await setState(env.DB, "quote_remigrate_v129", (start + 60 >= DEFAULT_US.length) ? { done: true } : { idx: start + 60 });
        }
        // [V12.12] 스파크(그래프) 없는 종목도 대상 포함 — 신규 종목은 quote는 있으나 일봉/스파크가 빔
        let sparkless = [];
        try {
          const sr = await env.DB.prepare("SELECT k FROM state WHERE k LIKE 'quote:%' AND json_extract(v,'$.spark') IS NULL LIMIT 15").all();
          sparkless = ((sr && sr.results) || []).map(function (r) { return String(r.k).slice(6); })
            .filter(function (s) { return DEFAULT_US.indexOf(s) >= 0 || DEFAULT_KR.indexOf(s) >= 0; });
        } catch (e) {}
        const targets = Array.from(new Set(missing.concat(remig).concat(sparkless))).slice(0, 90);
        if (targets.length) {
          resetFetchBudget(140);
          const got = await fetchBatchQuotes(targets, { DB: env.DB, maxFallback: targets.length });
          const now2 = Date.now(); const stmts2 = [];
          let dailyBudget = 15;   // [V12.12] 스파크라인 백필 — 일봉 없는 신규종목, 사이클당 15개
          for (const s of targets) {
            const q = got[s]; if (!q || q.price == null) continue;
            let prevQ = {};
            try { const e2 = await getState(env.DB, "quote:" + s, null); if (e2 && typeof e2 === "object") prevQ = e2; } catch (e) {}
            const merged = Object.assign({}, prevQ, {
              market: (s.endsWith(".KS") || s.endsWith(".KQ")) ? "kr" : "us",
              price: q.price, prevClose: q.prevClose, dayPct: q.dayPct, ts: now2
            });
            // [V12.12] 그래프(스파크)·기간수익률이 없는 신규 종목은 일봉을 즉시 당겨 채움
            if ((!merged.spark || !merged.spark.length) && dailyBudget > 0 && fetchBudgetLeft() > 2) {
              dailyBudget--;
              try {
                const dw = await fetchDailyWithFallback(s);
                const cl = dw && dw.data && dw.data.closes;
                if (Array.isArray(cl) && cl.length >= 2) {
                  merged.spark = cl.slice(-23).map(function (v) { return Math.round(v * 100) / 100; });
                  const L = cl.length, last = cl[L - 1];
                  const retN = function (n) { return (L > n && cl[L - 1 - n] > 0) ? ((last / cl[L - 1 - n]) - 1) * 100 : null; };
                  if (merged.return5 == null) merged.return5 = retN(5);
                  if (merged.return20 == null) merged.return20 = retN(20);
                  if (merged.return60 == null) merged.return60 = retN(60);
                }
              } catch (e) {}
            }
            // 시간외 필드는 새 값이 있을 때만 갱신(없으면 기존 유지)
            if (q.mstate != null) merged.mstate = q.mstate;
            if (typeof q.pre === "number" && q.pre > 0) { merged.pre = q.pre; merged.prePct = q.prePct; }
            if (typeof q.post === "number" && q.post > 0) { merged.post = q.post; merged.postPct = q.postPct; }
            if (typeof q.shares === "number" && q.shares > 0) merged.shares = q.shares;
            if (typeof q.mcap === "number" && q.mcap > 0) merged.mcap = q.mcap;
            stmts2.push(env.DB.prepare("INSERT INTO state (k, v, updated_ts) VALUES (?, ?, ?) ON CONFLICT(k) DO UPDATE SET v=excluded.v, updated_ts=excluded.updated_ts")
              .bind("quote:" + s, JSON.stringify(merged), now2));
          }
          for (let i = 0; i < stmts2.length; i += 50) { try { await env.DB.batch(stmts2.slice(i, i + 50)); } catch (e) {} }
          if (stmts2.length) { try { await log(env.DB, "INFO", null, "[V12.9] quote 백필/재기록 " + stmts2.length + "/" + targets.length + "건"); } catch (e) {} }
        }
      } catch (e) {}

      // 2+3) [신규] alt 슬리브 실시간 거래 — 원자재(cm)·미국국채(bdus)·한국국채(bdkr)
      //   기존 "매분 시세갱신 + 16:00 1회 거래"를 실시간(매 사이클 장중 매매)으로 통합.
      //   [예산 안전] 월 사용량이 altEnrichMaxUsageRatio(코어 셧다운 0.90보다 낮음) 초과 시
      //   alt 슬리브는 주식(코어)보다 먼저 양보해 한도 여유분을 항상 보장.
      try {
        const _acfg = migrateCfgToMarkets(Object.assign({}, DEFAULT_CFG, await getState(env.DB, "cfg", {})));
        let _altOk = true;
        if (_acfg.altRealtime === false) _altOk = false;
        if (_altOk) {
          try {
            const u = await getUsageState(env.DB);
            const lim = Object.assign({}, USAGE_LIMITS_DEFAULT, _acfg.usageLimits || {});
            const ratio = Math.max((u.data.requests || 0) / Math.max(1, lim.monthlyRequests), (u.data.cpuMs || 0) / Math.max(1, lim.monthlyCpuMs));
            if (ratio >= (_acfg.altEnrichMaxUsageRatio != null ? _acfg.altEnrichMaxUsageRatio : 0.82)) {
              _altOk = false;
              await log(env.DB, "WARN", null, "[ALT] 월 사용량 " + (ratio * 100).toFixed(1) + "% — alt 슬리브(원자재·국채) 양보(코어 거래 우선)");
            }
          } catch (e) {}
        }
        if (_altOk) {
          for (const _k of ["cm", "bdus", "bdkr"]) {
            try { await runAltSleeveCycle(env, _k); }
            catch (e) { try { await log(env.DB, "ERROR", null, "[SCHED] alt " + _k + " fail: " + e.message); } catch (e2) {} }
          }
        }
      } catch (e) { try { await log(env.DB, "ERROR", null, "[SCHED] alt sleeves fail: " + e.message); } catch (e2) {} }

      // 4) 환율 갱신 — [V9.1] 하루 1회(06:30) → 10분 주기 실시간화.
      //    기존엔 06:30 KST 1회만 갱신해 장중 내내 새벽 환율이 그대로 표시됐음(현실과 수 원대 차이).
      //    FX 휴장(주말) 제외, 마지막 갱신 후 10분 경과 시에만 실행 — 10쌍 fetch라 예산 부담 미미.
      try {
        if (isFxMarketOpen()) {
          const fxPrev = await getState(env.DB, "fx", null);
          const fxAge = (fxPrev && fxPrev.updatedAt) ? (Date.now() - fxPrev.updatedAt) : Infinity;
          if (fxAge > 10 * 60 * 1000) {
            try { await runFxUpdate(env); }
            catch (e) { try { await log(env.DB, "ERROR", null, "[SCHED] fx fail: " + e.message); } catch (e2) {} }
          }
        }
      } catch (e) {}

      // 5) 경제지표 갱신 (매일 07:00 KST) — runTradingCycle 내부에도 트리거가 있으나
      //    엔진 disabled 상태에서도 매크로는 갱신되도록 여기서도 안전하게 한 번 더 보장.
      if (isMacroTriggerTime()) {
        try { await runMacroUpdate(env); }
        catch (e) { try { await log(env.DB, "ERROR", null, "[SCHED] macro fail: " + e.message); } catch (e2) {} }
      }

      // 6) Vision AI 백엔드 스캔 — 매 cron에서 5개씩 처리 (24h 캐시, rate limit 안전)
      //    브라우저 없이도 차트 예측 결과가 항상 최신 상태 유지됨.
      try { await runVisionScanBackend(env); }
      catch (e) { try { await log(env.DB, "ERROR", null, "[SCHED] vision scan fail: " + e.message); } catch (e2) {} }

      // 7) SEC EDGAR 공시 스캔 — 미국 프리마켓 직전(UTC 08:00~08:30)에만, 거래 fetch와 분리
      //    최근 8-K/어닝 직후 미국 종목의 신규 진입을 보수화 (변동성 회피)
      try { await fetchSecFilings(env); }
      catch (e) { try { await log(env.DB, "ERROR", null, "[SCHED] sec fetch fail: " + e.message); } catch (e2) {} }

      // 7.5) [LUX-AI] 야간 자가학습 — 하루 1회. 반사실 라벨링 → 감성수집 → 6단 학습.
      //    미학습/표본부족이면 각 함수가 자동 대기(observe)라 거래영향 0.
      try {
        if (typeof LUXML !== "undefined" && LUXML.enabled) {
          const _aiDay = new Date().toISOString().slice(0, 10);
          const _aiLast = await getState(env.DB, "ai_trained_day", null);
          // [V12.37] 동시실행 방지 락 — 완료플래그(ai_trained_day)는 파이프라인 맨 끝에만 찍히는데,
          //   CPU예산 초과 등으로 중간에 끊기면 다음 cron(매분)마다 새 파이프라인이 겹쳐 실행되어
          //   서로 다른 실행이 mind_model 등 같은 상태를 경쟁적으로 덮어쓰는 위험이 있었다(회귀가드
          //   우회 원인 — 낡은 실행이 늦게 끝나며 새 실행의 정상 결과를 덮어씀). 15분 이상 된 락은
          //   죽은 실행으로 보고 자동 해제(영구 교착 방지).
          const _aiLock = await getState(env.DB, "ai_train_lock", null);
          const _aiLockFresh = _aiLock && (Date.now() - _aiLock < 900000);
          if (_aiLast !== _aiDay && !_aiLockFresh) {
            await setState(env.DB, "ai_train_lock", Date.now());
            // [V12.40 단계별 체크포인트] trainWindow 확대 후 전체 파이프라인 CPU가 300s 한도를 넘겨
            //   invocation이 중간에 죽고, 완료플래그를 못 찍어 15분마다 "처음부터" 무한 재시도하며
            //   하루 종일 CPU를 태우던 문제 수정. 각 단계가 끝날 때마다 오늘 날짜 도장을 찍어,
            //   재시도는 미완료 단계부터 "이어서" 진행 → 몇 번의 재시도에 걸쳐 반드시 완주한다.
            //   단계 자체가 CPU예산 초과로 죽으면 그 단계부터 재개(멱등 — 각 학습은 재실행 무해).
            const _stg = async function (nm, fn) {
              try {
                if ((await getState(env.DB, "ai_stage:" + nm, null)) === _aiDay) return;   // 오늘 이미 완료
                const _r = await fn();
                if (_r) await log(env.DB, "INFO", null, _r);
                await setState(env.DB, "ai_stage:" + nm, _aiDay);
              } catch (e) { try { await log(env.DB, "ERROR", null, "[STAGE:" + nm + "] " + (e && e.message)); } catch (e2) {} }
            };
            // (1) 반사실 후보 라벨링 — 성숙분(N일 경과)을 손절반영 경로로 라벨링해 표본 편입
            await _stg("cflabel", async function () {
              return await mlLabelCandidates(env.DB, async (sym, mkt, entryTs, horizon) => {
                try {
                  const dd = await getState(env.DB, "daily:" + sym, null);
                  if (!dd || !dd.closes || !dd.closes.length) return null;
                  // 진입 이후 경로가 필요 — 최근 (horizon+2)봉을 경로로 제공(손절선 도달 판정용).
                  const n = Math.max(1, horizon || 5) + 2;
                  // [V17] alpha 라벨용 지수 경로(동일 창) — 종목 경로와 같은 최근 n봉으로 정렬
                  let idxCloses = null;
                  try { const ic = await _mlLoadIndexCloses(env.DB, mkt); if (ic && ic.length >= 2) idxCloses = ic.slice(-n); } catch (e) {}
                  return { closes: dd.closes.slice(-n), idxCloses: idxCloses };
                } catch (e) { return null; }
              }, {});
            });
            // (2) 외부 감성 수집 — SENTI_SOURCES에 URL이 채워진 경우만 동작(없으면 스킵)
            await _stg("senti", async function () { const _se = await sentiFetchAndStore(env.DB, null, null); return (_se && !/스킵/.test(_se)) ? _se : null; });
            // (2.4) [HIST] 딥-히스토리 로테이션 — range=max 장기이력(폭락장 포함)을 hist:로 갱신(수확이 사용)
            //   [V12.47] ★원인 발견★ 이 단계 전용 fetch예산 리셋이 없어 앞선 거래사이클/스캔이 남긴
            //   찌꺼기 예산(종종 20 미만)으로 돌았음 → deepFetchPerNight:100 목표를 거의 못 채우고
            //   fetchBudgetLeft()<20에서 조기중단, 딥이력 커버리지(358/900+종목)가 며칠째 정체된 원인.
            //   LLM(400)·시세백필(140)과 동일 패턴으로 이 단계만의 깨끗한 예산 부여.
            try { resetFetchBudget(130); } catch (e0) {}
            await _stg("deephist", async function () { return await harvestDeepFetchNightly(env.DB); });
            // (2.45) [XS] 유니버스 횡단면 랭크 패널 — 수확 전에 갱신(수확이 z-score 정규화에 사용)
            await _stg("xspanel", async function () { return await mlBuildXSPanel(env.DB); });
            // (2.5) [HARVEST] 시장 자기지도 표본 수확 — 전 종목 일봉에서 "피처→N일 뒤 방향" 대량 편입
            await _stg("harvest", async function () { return await mlMarketHarvestNightly(env.DB); });
            // (3) 7단 학습 파이프라인(순서 고정: L1→노이즈→앙상블→MIND→DNN→GBDT)
            await _stg("l1", async function () { return await mlTrainNightly(env.DB); });
            await _stg("bandit", async function () { return await mlBanditNoiseNightly(env.DB); });
            await _stg("brain", async function () { return await mlBrainTrainNightly(env.DB); });
            await _stg("mind", async function () { return await mlMindTrainNightly(env.DB); });
            await _stg("dnn", async function () { return await mlDNNTrainNightly(env.DB); });
            await _stg("gbdt", async function () { return await mlGBDTTrainNightly(env.DB); });
            // (4) [V4] 위원회 확률 보정(온도 스케일링) — 결합확률의 과신/과소신 교정
            await _stg("calibrate", async function () { return await mlCalibrateCommittee(env.DB); });
            // (4.5) [V6] 전 종목 야간 AI 스캔 — 유니버스 전체 승률예측(AI 픽·리포트 커버리지)
            await _stg("uniscan", async function () { return await mlUniverseScanNightly(env.DB); });
            // (4.6) [V9.6] 뉴스·여론 기반 "내일 오를 종목" 예측(온라인학습) + 재무 저가중 하방가드
            await _stg("newsnext", async function () { return await mlNewsNextDayNightly(env.DB); });
            // (5) [V5] 매월 1일: 지난달 투자 리포트 자동 생성(캐시라 중복 무해)
            try {
              if (new Date().getUTCDate() === 1) {
                const _pm = new Date(); _pm.setUTCDate(0);   // 지난달 말일
                const _r = await mlMonthlyReport(env.DB, _pm.toISOString().slice(0, 7), true);
                if (_r && !_r.error) await log(env.DB, "INFO", null, "[REPORT] " + _r.ym + " 월간 리포트 생성 완료");
              }
            } catch (e) {}
            // [V12.59] ★열화 플래그 이월 버그 수정★ model_drift는 거래 사이클에서 쓰기만 되고
            //   mlDataHealth(대시보드)에서 읽을 뿐, 학습 파이프라인이 소비하지도·해제하지도 않았다
            //   → 한번 열화 뜨면 재학습 후에도 영원히 "열화" 표시(retrainOnDrift가 사실상 무동작).
            //   전체 재학습을 완주했으니 플래그를 해제 → 다음 거래 사이클의 mlDriftCheck가 새 모델
            //   기준으로 재평가(여전히 미달이면 다시 셋). 이로써 "열화→재학습→해소" 루프가 실제로 닫힌다.
            try { await env.DB.prepare("DELETE FROM state WHERE k = 'model_drift'").run(); } catch (e) {}
            await setState(env.DB, "ai_trained_day", _aiDay);
            try { await env.DB.prepare("DELETE FROM state WHERE k = 'ai_train_lock'").run(); } catch (e2) {}
            try { await log(env.DB, "INFO", null, "[SCHED] 야간 AI 파이프라인 완주(" + _aiDay + ")"); } catch (e2) {}
          }
        }
      } catch (e) { try { await log(env.DB, "ERROR", null, "[SCHED] AI train fail: " + e.message); } catch (e2) {} }

      // 8) [실시간] 분(分) 내 빠른 포지션 감시 — 남은 시간만큼 sleep 서브틱으로 손절/익절 점검
      try { await runFastWatch(env, __cronStart); }
      catch (e) { try { await log(env.DB, "ERROR", null, "[SCHED] fast watch fail: " + e.message); } catch (e2) {} }

      // [PAID 가드] 이번 invocation 사용량 누적 — request 1건 + (비sleep경과×보정) CPU 추정
      try { await tickUsage(env.DB, __cronStart, __usageCalib, __fetchBudget.used || 0); } catch (e) {}
    })());
  }
};

// [검증용 named export] Cloudflare Worker는 default export만 사용하므로 무해.
//   로컬 백테스트/단위검증 스크립트에서 핵심 함수를 직접 호출하기 위함.
export {
  DEFAULT_CFG, migrateCfgToMarkets, evaluateAllStrategies, evaluateTrendEntry, evaluateSnapEntry,
  evaluateSell, backtestSymbol, backtestStats, backtestStatsBySignal,
  getRSI, getMA, getATR, getNDayHigh, getStrategyRules, fetchDailyForBacktest,
  fetchMinuteBars, confirmIntradayEntry
};
